// Soccer-square stats for the stat videos: every goal of the men's world
// championship (2018, 2022, 2026) on the square it would have won, generated by
// scripts/seo/soccerStats.ts from openfootball's public-domain worldcup.json.
// Copy names the tournament without its trademarked name, like "the big game".

import { GOALS, MATCHES, NO_GOAL_MATCHES, SECOND_HALF_STOPPAGE, FIRST_HALF_STOPPAGE, SQUARE_GOALS, YEARS } from "../../../scripts/seo/data/soccerMinutes.ts";

export { FIRST_HALF_STOPPAGE, GOALS, MATCHES, NO_GOAL_MATCHES, SECOND_HALF_STOPPAGE, SQUARE_GOALS, YEARS };

/** Share (%) of goals landing on square m. */
export const minutePct = (m: number): number => (100 * SQUARE_GOALS[m]) / GOALS;

/** Goals in each row of the board (the minute's tens digit). */
export const ROW_GOALS = Array.from({ length: 10 }, (_, r) => SQUARE_GOALS.slice(r * 10, r * 10 + 10).reduce((a, b) => a + b, 0));
